/* @lc app=leetcode id=3771 lang=kotlin */ class Solution { fun totalScore(hp: Int, damage: IntArray, requirement: IntArray): Long = damage.runningFold(0L) { a, b -> a + b }.let { Q -> damage.indices.sumOf { i -> (requirement[i] + Q[i + 1] - hp).let { T -> (i + 1 - generateSequence(0 to i + 1) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (Q[m] >= T) lo to m else m + 1 to hi } }.last().first).toLong() } } } }